/// Fields as generated by the model or by Basic naming, before validation (3.8).
public struct GeneratedFields: Codable, Sendable, Hashable {
    public var kind: KindRef
    public var source: String?
    public var subject: String
    /// Index into the date candidates the model saw, or nil.
    public var dateChoice: Int?

    public init(kind: KindRef, source: String?, subject: String, dateChoice: Int?) {
        self.kind = kind
        self.source = source
        self.subject = subject
        self.dateChoice = dateChoice
    }
}

/// How the fields were produced.
public enum NamingPath: String, Codable, Sendable, Hashable {
    case model
    case basic
    case typed
}

/// Evidence gathered during extraction, used to validate fields (3.9). Extracted text is
/// held in memory only (3.18) and never stored.
public struct Evidence: Sendable, Hashable {
    public var text: String
    public var downloadDomain: String?
    public var appName: String?
    public var dateCandidates: [DateCandidate]
    public var captureDate: DateValue?
    public var dateAdded: DateValue?
    public var creationDate: DateValue?
    public var isScreenshot: Bool
    public var topLabelConfidence: Double?
    public var titleLine: String?
    public var metadataOnly: Bool

    public init(
        text: String = "", downloadDomain: String? = nil, appName: String? = nil,
        dateCandidates: [DateCandidate] = [], captureDate: DateValue? = nil, dateAdded: DateValue? = nil,
        creationDate: DateValue? = nil, isScreenshot: Bool = false, topLabelConfidence: Double? = nil,
        titleLine: String? = nil, metadataOnly: Bool = false
    ) {
        self.text = text
        self.downloadDomain = downloadDomain
        self.appName = appName
        self.dateCandidates = dateCandidates
        self.captureDate = captureDate
        self.dateAdded = dateAdded
        self.creationDate = creationDate
        self.isScreenshot = isScreenshot
        self.topLabelConfidence = topLabelConfidence
        self.titleLine = titleLine
        self.metadataOnly = metadataOnly
    }

    /// Characters of extracted text, ignoring whitespace (3.9: "≥ 20 characters of text").
    public var textCharacterCount: Int { text.filter { !$0.isWhitespace }.count }
}

/// Why a part of the name is what it is ("Why this name?", 3.15). Stored, so the
/// explanation is capped at 200 characters (3.18).
public struct PartEvidence: Codable, Sendable, Hashable {
    public var token: TokenKind
    public var explanation: String

    public init(token: TokenKind, explanation: String) {
        self.token = token
        self.explanation = String(explanation.prefix(Defaults.storedFieldMaxCharacters))
    }
}

public enum Confidence: String, Codable, Sendable, Hashable {
    case high, low
}

/// Reasons a proposal is Low confidence, shown in Review.
public enum LowConfidenceReason: String, Codable, Sendable, Hashable, CaseIterable {
    case missingRequiredToken
    case littleContent
    case guardrailOrRefusal
    case guardsRemovedMostOfSubject
    case nameUnchanged
    case metadataOnly
    case basicNamingForced

    public var explanation: String {
        switch self {
        case .missingRequiredToken: "A required part of the name couldn't be filled."
        case .littleContent: "The file had little readable content."
        case .guardrailOrRefusal: "Apple Intelligence declined to name this file, so Basic naming was used."
        case .guardsRemovedMostOfSubject: "Most of the suggested subject was removed for privacy."
        case .nameUnchanged: "The suggested name is the same as the current one."
        case .metadataOnly: "Only the file's metadata could be read."
        case .basicNamingForced: "Basic naming was used after an error."
        }
    }
}

/// A complete proposal: fields, the formatted name, destination, confidence and evidence (3.3).
public struct Proposal: Codable, Sendable, Hashable {
    public var fields: NameFields
    public var fileName: String
    public var parts: [RenderedPart]
    public var evidence: [PartEvidence]
    public var confidence: Confidence
    public var lowReasons: [LowConfidenceReason]
    public var styleID: String
    public var styleVersion: Int
    public var path: NamingPath
    public var ruleID: String?
    public var destinationID: String?
    public var subfolder: [String]
    public var language: NameLanguage
    public var isScreenshot: Bool

    public init(
        fields: NameFields, fileName: String, parts: [RenderedPart], evidence: [PartEvidence],
        confidence: Confidence, lowReasons: [LowConfidenceReason], styleID: String, styleVersion: Int,
        path: NamingPath, ruleID: String? = nil, destinationID: String? = nil, subfolder: [String] = [],
        language: NameLanguage, isScreenshot: Bool
    ) {
        self.fields = fields
        self.fileName = fileName
        self.parts = parts
        self.evidence = evidence
        self.confidence = confidence
        self.lowReasons = lowReasons
        self.styleID = styleID
        self.styleVersion = styleVersion
        self.path = path
        self.ruleID = ruleID
        self.destinationID = destinationID
        self.subfolder = subfolder
        self.language = language
        self.isScreenshot = isScreenshot
    }
}
